Scripts.OnLoad:

Kitty.protectFunction(function()
	if(Kitty.onLoad ~= nil) then
		Kitty.onLoad(this);
	end
end)();

Scripts.OnEvent:

Kitty.protectFunction(function()
	if(Kitty.onEvent ~= nil) then
		Kitty.onEvent(this, event, arg1, arg2, arg3, arg4);
	end
end)();

Scripts.OnUpdate:

Kitty.protectFunction(function()
	if(Kitty.onUpdate ~= nil) then
		Kitty.onUpdate(this, elapsedTime);
	end
end)();

Scripts.OnClick:

Kitty.protectFunction(function()
	if(KittyBasicConfigFrame:IsVisible()) then
		KittyBasicConfigFrame:Hide();
	else
		KittyBasicConfigFrame:Show();
	end
end)();

Scripts.OnEnter:

Kitty.protectFunction(function()
	GameTooltip:Show();
	GameTooltip:SetOwner(this, "ANCHOR_BOTTOMRIGHT", 0, 0);
	GameTooltip:SetText("Kitty Combo");
	GameTooltip:AddSeparator();
	GameTooltip:AddLine(UI_MINIMAPBUTTON_MOVE, 0, 0.75, 0.95);
end)();

Scripts.OnClick:
				
				Kitty.protectFunction(function()
					Kitty.debugPrint("KittyAddonManagerMiniButton:OnClick.");

					if(KittyBasicConfigFrame:IsVisible()) then
						KittyBasicConfigFrame:Hide();
					else
						KittyBasicConfigFrame:Show();
